import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/commands.md","filePath":"en/modules/skills/commands.md","lastUpdated":0}`),a={name:`en/modules/skills/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command of EmakiSkills is <code>/emakiskills</code>, with <code>/eskills</code> as an alias. Players use it to open the skill GUI, toggle cast mode, and upgrade skills; administrators use it for level management, slot cleanup, profile inspection, skill-source resync, and reloading configuration.</p><h2 id="command-registration" tabindex="-1">Command registration <a class="header-anchor" href="#command-registration" aria-label="Permalink to “Command registration”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Main command</td><td><code>/emakiskills</code></td></tr><tr><td>Alias</td><td><code>/eskills</code></td></tr><tr><td>Command permission</td><td><code>emakiskills.use</code></td></tr><tr><td>Help</td><td><code>/eskills</code> or <code>/eskills help</code></td></tr></tbody></table><p>The command itself is registered with <code>emakiskills.use</code>: without it the whole command (including <code>help</code>) cannot run, so the <code>emakiskills.admin</code> fallbacks inside subcommands are never reached. That permission defaults to <code>true</code>, so the practical constraint only appears when a permission is explicitly negated.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/eskills help</code></td><td>Command permission</td><td>Print the command help list. Also shown when running <code>/eskills</code> with no arguments. The help branch adds no extra check.</td></tr><tr><td><code>/eskills gui</code></td><td><code>emakiskills.use</code> or <code>emakiskills.admin</code></td><td>Open the skill GUI. Non-player senders are told the command is player-only.</td></tr><tr><td><code>/eskills castmode &lt;on|off|toggle&gt;</code></td><td><code>emakiskills.use</code> or <code>emakiskills.admin</code></td><td>Enable, disable, or toggle cast mode.</td></tr><tr><td><code>/eskills upgrade &lt;skill&gt;</code></td><td><code>emakiskills.use</code> or <code>emakiskills.admin</code></td><td>Try to upgrade a skill; feedback comes from the <code>upgrade.*</code> keys.</td></tr><tr><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>Get a player&#39;s skill level.</td></tr><tr><td><code>/eskills level set &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>Set a player&#39;s skill level.</td></tr><tr><td><code>/eskills level add &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>Add levels to a player&#39;s skill.</td></tr><tr><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td><code>emakiskills.admin</code></td><td>Clear a player&#39;s skill slot binding.</td></tr><tr><td><code>/eskills inspect [player]</code></td><td><code>emakiskills.use</code> or <code>emakiskills.admin</code></td><td>Inspect the profile and the bound trigger of each slot.</td></tr><tr><td><code>/eskills resync [player]</code></td><td><code>emakiskills.admin</code></td><td>Validate and resync the player&#39;s skill slot bindings. The player may be omitted to target yourself.</td></tr><tr><td><code>/eskills debug [status|on|off|player|module] [...]</code></td><td><code>emakiskills.debug</code> or <code>emakiskills.admin</code></td><td>Print or toggle debug state. Skill modules are <code>cast</code>, <code>unlock</code>, <code>upgrade</code>, and <code>slot</code>.</td></tr><tr><td><code>/eskills reload</code></td><td><code>emakiskills.reload</code> or <code>emakiskills.admin</code></td><td>Asynchronously reload skills, resources, GUI, language, and main configuration, then report the elapsed time.</td></tr></tbody></table><p>An unknown subcommand replies with <code>general.unknown_command</code>. <code>level</code> and <code>clearslot</code> require a valid argument count and integer <code>value</code> / <code>slot</code>, otherwise they reply with <code>general.invalid_args</code>.</p><h3 id="tab-completion" tabindex="-1">Tab completion <a class="header-anchor" href="#tab-completion" aria-label="Permalink to “Tab completion”">​</a></h3><table tabindex="0"><thead><tr><th>Position</th><th>Suggestions</th></tr></thead><tbody><tr><td>First argument</td><td>The ten subcommand literals.</td></tr><tr><td><code>castmode</code> argument 2</td><td><code>on</code>, <code>off</code>, <code>toggle</code>.</td></tr><tr><td><code>upgrade</code> argument 2</td><td>Skills the player has unlocked, has upgrades enabled for, and has not maxed; from console, all skill ids.</td></tr><tr><td><code>level</code> argument 2</td><td><code>get</code>, <code>set</code>, <code>add</code>.</td></tr><tr><td><code>clearslot</code> argument 2 / <code>level</code> argument 3</td><td>Online player names.</td></tr><tr><td><code>clearslot</code> argument 3</td><td>Slots <code>0</code>~<code>8</code>.</td></tr><tr><td><code>level</code> argument 4</td><td>All skill ids.</td></tr><tr><td><code>level set/add</code> argument 5</td><td><code>1</code>, <code>2</code>, <code>5</code>, <code>10</code>.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiskills.use</code></td><td>true</td><td>Allows basic skill usage, GUI access, cast mode switching, and casting; also the command registration permission.</td></tr><tr><td><code>emakiskills.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiskills.admin</code></td><td>op</td><td>Allows level management, slot clearing, resync, and acts as an administrative fallback for basic features.</td></tr><tr><td><code>emakiskills.debug</code></td><td>op</td><td>Allows debug output.</td></tr></tbody></table><h2 id="which-command-first" tabindex="-1">Which command first <a class="header-anchor" href="#which-command-first" aria-label="Permalink to “Which command first”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Run first</th><th>Purpose</th></tr></thead><tbody><tr><td>A player wants to view or bind skills</td><td><code>/eskills gui</code></td><td>Open the skill interface.</td></tr><tr><td>An active skill cannot be cast</td><td><code>/eskills inspect [player]</code></td><td>Check whether the profile is loaded and which trigger each slot has bound.</td></tr><tr><td>Skills did not refresh after an equipment change</td><td><code>/eskills resync &lt;player&gt;</code></td><td>Re-scan skill sources.</td></tr><tr><td>A skill level looks wrong</td><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td>Confirm the stored level.</td></tr><tr><td>A slot is bound to a deleted skill</td><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td>Clear that slot.</td></tr><tr><td>Skills, resources, or GUI files changed</td><td><code>/eskills reload</code></td><td>Reload the runtime configuration.</td></tr></tbody></table><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to “Common operations”">​</a></h2><h3 id="open-the-skill-gui" tabindex="-1">Open the skill GUI <a class="header-anchor" href="#open-the-skill-gui" aria-label="Permalink to “Open the skill GUI”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills gui</span></span></code></pre></div><p>The skill GUI shows unlocked skills, skill levels, slot bindings, the upgrade entry, and the trigger-selection entry.</p><h3 id="toggle-cast-mode" tabindex="-1">Toggle cast mode <a class="header-anchor" href="#toggle-cast-mode" aria-label="Permalink to “Toggle cast mode”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills castmode toggle</span></span>
<span class="line"><span>/eskills castmode on</span></span>
<span class="line"><span>/eskills castmode off</span></span></code></pre></div><p>Cast mode affects active skill triggering. By default the F key enters and leaves cast mode; whether the state survives a rejoin is controlled by <code>cast_mode.restore_last_state_on_join</code>.</p><h3 id="manage-skill-levels" tabindex="-1">Manage skill levels <a class="header-anchor" href="#manage-skill-levels" aria-label="Permalink to “Manage skill levels”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills level get Steve fireball</span></span>
<span class="line"><span>/eskills level set Steve fireball 3</span></span>
<span class="line"><span>/eskills level add Steve fireball 1</span></span></code></pre></div><p>Level changes affect skill parameters, resource costs, script variables, and upgrade checks. Levels are clamped into <code>[1, max_level]</code>; a skill without upgrades enabled has a maximum of <code>1</code>. Use <code>inspect</code> afterwards to confirm the stored value.</p><h3 id="clear-a-slot" tabindex="-1">Clear a slot <a class="header-anchor" href="#clear-a-slot" aria-label="Permalink to “Clear a slot”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills clearslot Steve 1</span></span></code></pre></div><p>Use it when a slot points at a deleted skill, a trigger conflicts, or the GUI cannot unbind. An invalid slot is rejected by the state service and reports failure.</p><h3 id="resync-skill-sources" tabindex="-1">Resync skill sources <a class="header-anchor" href="#resync-skill-sources" aria-label="Permalink to “Resync skill sources”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills resync Steve</span></span></code></pre></div><p>Useful when:</p><ul><li>Equipment-provided skills did not refresh after an equipment change.</li><li>EmakiItem set or item effects changed.</li><li>An external module granted or removed a skill source.</li><li>Online players need a refresh after a config reload.</li></ul><h3 id="print-debug-information" tabindex="-1">Print debug information <a class="header-anchor" href="#print-debug-information" aria-label="Permalink to “Print debug information”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/eskills debug</span></span>
<span class="line"><span>/eskills debug status</span></span>
<span class="line"><span>/eskills debug on</span></span>
<span class="line"><span>/eskills debug off</span></span>
<span class="line"><span>/eskills debug player Steve</span></span>
<span class="line"><span>/eskills debug module cast</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td>Print the current debug state and tracked players. <code>debug</code> with no arguments prints the same status, and any unrecognized subcommand falls back to it.</td></tr><tr><td><code>on</code> / <code>off</code></td><td>Enable or disable all debug output.</td></tr><tr><td><code>player &lt;player&gt;</code></td><td>Track debug output for one player.</td></tr><tr><td><code>module &lt;module&gt;</code></td><td>Toggle a single debug module. Skill modules are <code>cast</code>, <code>unlock</code>, <code>upgrade</code>, and <code>slot</code>; shared modules are <code>action</code>, <code>item_operation</code>, <code>variables</code>, <code>placeholder</code>, <code>gui</code>, and <code>chat_input</code>.</td></tr></tbody></table><p>The in-game help text prints <code>debug &lt;status|player|module|all&gt; [...]</code>; the subcommands above are the actual ones.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Skills do not appear: check that the definition loaded, that the player owns a skill source, and that the level is greater than 0.</li><li>A skill cannot be cast: check cast mode, trigger binding, cooldowns, the global forced delay, resource costs, and conditions.</li><li>Passive skills do not fire: check <code>trigger_type: passive</code>, <code>passive_triggers</code>, and that the passive trigger is enabled globally.</li><li>Binding fails in the GUI: check whether the trigger is disabled, conflicts with an existing binding, or the slot index is invalid.</li><li>A MythicMobs skill has no effect: check that MythicMobs is installed, the skill ID is correct, and the script mode is <code>mythic</code> or <code>hybrid</code>.</li><li>Players see no failure reason: messages come from <code>lang/&lt;language&gt;.yml</code>; confirm that key exists instead of editing the internal reason key.</li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};